                    writer.WriteNumber("location_restriction_radius_meters", taskReduced.LocationRestrictionRadiusMetersOption.Value!.Value);
                else
                    writer.WriteNull("location_restriction_radius_meters");

            if (taskReduced.CustomField1 != null)
                writer.WriteString("custom_field_1", taskReduced.CustomField1);
            else
                writer.WriteNull("custom_field_1");

            if (taskReduced.CustomField2 != null)
                writer.WriteString("custom_field_2", taskReduced.CustomField2);
            else
                writer.WriteNull("custom_field_2");

            if (taskReduced.CustomField3 != null)
                writer.WriteString("custom_field_3", taskReduced.CustomField3);
            else
                writer.WriteNull("custom_field_3");
        }
    }
}
